-- 2026-09-28 창고 규모 상품 마스터. 고정 검증셋(docs/evidence/eval/per_item_a.json)의 바코드·실측 치수 1736품목(13자리 바코드만 — gtin 컬럼이 char(13)이라 짧은 바코드는 조회에서 빠진다)을
-- 상품으로 넣는다. 8종만 쓴 09-22·09-25 포장 측정을 상품 수천 종에서 다시 재기 위해서다.
-- 이름·이미지·분류는 자리표시(화면 확인 안 함). 무게는 부피×0.3 g/cm³ 가정값(데이터셋에 무게 없음).
-- E호(48×38×34) 안에 마진 3cm 를 두고 들어가는 품목만 넣는다(초과 245품목 제외).
-- 재고는 product.stock_qty(원장 이전 코드용)와 원장 ADJUST + stock_balance(원장 코드용) 양쪽에 5,000 씩.
-- ref_type = 'DS_PRODUCTS'. 한 번만 돌린다. 되돌리기: ds-products-delete.sql
\set ON_ERROR_STOP on
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM product WHERE name LIKE 'DS %') THEN RAISE EXCEPTION 'dataset products already present'; END IF;
END $$;
BEGIN;
LOCK TABLE stock_balance IN EXCLUSIVE MODE;
CREATE TEMP TABLE ds(gtin text, w numeric, l numeric, h numeric, kg numeric) ON COMMIT DROP;
                     dim_status, dim_method, stock_qty)
SELECT gtin, 'DS ' || gtin, 'C2010', 'https://placehold.co/300?text=ds', 'MASTER', w, l, h, kg,
       'CONFIRMED', 'MANUAL', 5000 FROM ds;
SELECT p.id, 'ADJUST', 5000, 'DS_PRODUCTS', p.id, timestamp '2026-09-27 00:00:00' + p.id * interval '10 ms',
       '창고 규모 상품 마스터 — 초기 재고'
  FROM product p JOIN ds ON ds.gtin = p.gtin;
SELECT p.id, COALESCE(SUM(t.qty_delta), 0), COALESCE(MAX(t.id), 0), now()
  FROM product p JOIN ds ON ds.gtin = p.gtin LEFT JOIN inventory_tx t ON t.product_id = p.id GROUP BY p.id
ON CONFLICT (product_id) DO UPDATE SET qty = EXCLUDED.qty, last_tx_id = EXCLUDED.last_tx_id, computed_at = now();
COMMIT;
VACUUM (ANALYZE) product; VACUUM (ANALYZE) inventory_tx; VACUUM (ANALYZE) stock_balance;
SELECT 'products' AS k, count(*) AS n, count(*) FILTER (WHERE name LIKE 'DS %') AS ds FROM product;
SELECT 'tx' AS k, count(*) AS n, max(id) AS max_id FROM inventory_tx;
